namespace datagraph.data.graph.panel.model.column;




using docking.widgets.trable;
using docking.widgets.trable;
using generic.theme;

/**
 * Column renderer for the values column. Used to change the foreground color for values.
 */
public class ValueColumnRenderer : DefaultGTrableCellRenderer<string> {
	private Color valueColor = new GColor("color.fg.datagraph.value");

	/* @Override */
	public Component getCellRenderer(GTrable<object> trable, string value, bool isSelected,
			bool hasFocus, int row, int column) {

		base.getCellRenderer(trable, value, isSelected, hasFocus, row, column);
		if (value.startsWith(" =") && !isSelected) {
			setForeground(valueColor);
		}
		return this;
	}
}
